CREATE OR REPLACE FUNCTION public.complete_customer_experience_send(p_queue_id uuid, p_provider_message_id text, p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_job public.crm_automation_queue%rowtype;
  v_exp public.crm_customer_experience%rowtype;
  v_provider_id text := nullif(left(trim(coalesce(p_provider_message_id, '')), 255), '');
begin
  if p_kind not in ('satisfaction_request','review_invitation') then
    raise exception 'Unsupported customer experience send kind' using errcode = '22023';
  end if;
  if v_provider_id is null then
    raise exception 'Provider message id is required to finalize a send' using errcode = '22023';
  end if;

  select * into v_job
  from public.crm_automation_queue
  where id = p_queue_id
  for update;

  if not found or v_job.status <> 'processing'
     or v_job.source_type <> 'customer_experience'
     or v_job.event_type <> p_kind then
    return jsonb_build_object('conflict', true, 'reason', 'queue_state');
  end if;

  select * into v_exp
  from public.crm_customer_experience
  where id::text = v_job.source_id
  for update;

  if not found then
    return jsonb_build_object('conflict', true, 'reason', 'experience_missing');
  end if;

  if p_kind = 'satisfaction_request' and v_exp.status <> 'pending_send' then
    return jsonb_build_object('conflict', true, 'reason', 'experience_state');
  end if;
  if p_kind = 'review_invitation' and v_exp.status not in ('review_pending','recovery_resolved') then
    return jsonb_build_object('conflict', true, 'reason', 'experience_state');
  end if;

  update public.crm_automation_queue
  set status = 'sent',
      locked_at = null,
      provider_message_id = v_provider_id,
      completed_at = now(),
      last_error = null,
      updated_at = now()
  where id = v_job.id;

  if p_kind = 'satisfaction_request' then
    update public.crm_customer_experience
    set status = 'awaiting_response',
        request_queue_id = v_job.id,
        request_provider_message_id = v_provider_id,
        requested_at = coalesce(requested_at, now()),
        updated_at = now()
    where id = v_exp.id;
  else
    update public.crm_customer_experience
    set status = 'review_invited',
        review_queue_id = v_job.id,
        review_invited_at = coalesce(review_invited_at, now()),
        metadata = metadata || jsonb_build_object('review_provider_message_id', v_provider_id),
        updated_at = now()
    where id = v_exp.id;
  end if;

  insert into public.crm_automation_attempts(
    queue_id, attempt_number, outcome, detail, provider_message_id
  ) values (
    v_job.id,
    coalesce(v_job.attempts, 0),
    'succeeded',
    'Aceito pela API oficial do WhatsApp e conciliado com a experiência.',
    v_provider_id
  )
  on conflict (queue_id, attempt_number, outcome) do update
    set detail = excluded.detail,
        provider_message_id = excluded.provider_message_id;

  return jsonb_build_object(
    'conflict', false,
    'experienceId', v_exp.id,
    'status', 'sent',
    'attemptLogged', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_new_main_crm_followups()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_task jsonb;
  v_task_id text;
  v_lead_id text;
begin
  if new.id <> 'main' or new.data is null then
    return new;
  end if;

  for v_task in
    select item
    from jsonb_array_elements(coalesce(new.data->'tasks', '[]'::jsonb)) as t(item)
  loop
    v_task_id := nullif(btrim(v_task->>'id'), '');
    v_lead_id := nullif(btrim(v_task->>'leadId'), '');

    if v_task_id is null or v_lead_id is null then
      continue;
    end if;

    if lower(coalesce(v_task->>'done', 'false')) = 'true' then
      continue;
    end if;

    if coalesce(v_task->>'date', '') !~ '^\d{4}-\d{2}-\d{2}$' then
      continue;
    end if;

    if not exists (
      select 1
      from jsonb_array_elements(coalesce(new.data->'leads', '[]'::jsonb)) as l(item)
      where l.item->>'id' = v_lead_id
    ) then
      continue;
    end if;

    if exists (
      select 1
      from jsonb_array_elements(coalesce(old.data->'tasks', '[]'::jsonb)) as o(item)
      where o.item->>'id' = v_task_id
    ) then
      continue;
    end if;

    perform public.enqueue_crm_automation(
      'crm:lead_follow_up_requested:task:' || v_task_id,
      'lead_follow_up_requested',
      'task',
      v_task_id,
      null,
      jsonb_build_object(
        'source_type', 'task',
        'source_id', v_task_id,
        'occurred_at', now(),
        'task', 'follow_up_lead',
        'origin', 'crm_app_state_trigger'
      ),
      'internal',
      now(),
      3
    );
  end loop;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_customer_experience_response(p_provider_message_id text, p_contact_wa_id text, p_context_provider_message_id text, p_satisfaction text, p_response_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_exp public.crm_customer_experience%rowtype;
  v_queue_id uuid;
  v_phone text := regexp_replace(coalesce(p_contact_wa_id, ''), '[^0-9]', '', 'g');
  v_response_id text := left(trim(coalesce(p_provider_message_id, '')), 255);
  v_context_id text := left(trim(coalesce(p_context_provider_message_id, '')), 255);
  v_candidate_ids uuid[];
begin
  if p_satisfaction is null or p_satisfaction not in ('very_good','good','needs_improvement') then
    raise exception 'Unsupported satisfaction value' using errcode = '22023';
  end if;
  if length(v_response_id) = 0 or length(v_phone) < 10 or length(v_phone) > 15 then
    raise exception 'Invalid customer experience response identifiers' using errcode = '22023';
  end if;

  -- A replay cannot be reassigned to a newer survey, even without context.
  select * into v_exp from public.crm_customer_experience
  where recipient_phone = v_phone and response_provider_message_id = v_response_id
  limit 1;
  if found then
    return jsonb_build_object('matched', true, 'duplicate', true, 'action', 'none', 'experienceId', v_exp.id);
  end if;

  if length(v_context_id) > 0 then
    select * into v_exp
    from public.crm_customer_experience
    where recipient_phone = v_phone
      and request_provider_message_id = v_context_id
    order by requested_at desc nulls last, created_at desc
    limit 1
    for update;
  else
    -- Include answered surveys so absent context cannot redirect an old click.
    select array_agg(id order by requested_at desc nulls last, created_at desc)
      into v_candidate_ids
    from public.crm_customer_experience
    where recipient_phone = v_phone
      and requested_at >= now() - interval '7 days';

    if coalesce(cardinality(v_candidate_ids), 0) > 1 then
      return jsonb_build_object('matched', false, 'ambiguous', true, 'action', 'none');
    end if;
    if coalesce(cardinality(v_candidate_ids), 0) = 1 then
      select * into v_exp
      from public.crm_customer_experience
      where id = v_candidate_ids[1]
      for update;
    end if;
  end if;

  if v_exp.id is null then
    return jsonb_build_object('matched', false, 'action', 'none');
  end if;

  if v_exp.response_provider_message_id is not null then
    return jsonb_build_object('matched', true, 'duplicate', true, 'action', 'none', 'experienceId', v_exp.id);
  end if;

  -- Recheck state after the row lock, including concurrent responses.
  if v_exp.status <> 'awaiting_response' then
    return jsonb_build_object('matched', false, 'action', 'none');
  end if;

  update public.crm_customer_experience
  set satisfaction = p_satisfaction,
      response_text = left(coalesce(p_response_text, ''), 1000),
      response_provider_message_id = v_response_id,
      responded_at = now(),
      updated_at = now()
  where id = v_exp.id;

  if p_satisfaction = 'needs_improvement' then
    v_queue_id := public.enqueue_crm_automation(
      'crm:service_recovery_required:experience:' || v_exp.id::text,
      'service_recovery_required',
      'customer_experience',
      v_exp.id::text,
      null,
      jsonb_build_object(
        'experience_id', v_exp.id,
        'customer_id', v_exp.customer_id,
        'first_name', v_exp.first_name,
        'service_name', v_exp.service_name,
        'recipient_phone', v_exp.recipient_phone,
        'response_text', left(coalesce(p_response_text, ''), 1000),
        'satisfaction', p_satisfaction
      ),
      'internal',
      now(),
      3
    );

    update public.crm_customer_experience
    set status = 'recovery_required',
        recovery_queue_id = v_queue_id,
        recovery_opened_at = coalesce(recovery_opened_at, now()),
        updated_at = now()
    where id = v_exp.id;

    return jsonb_build_object(
      'matched', true, 'action', 'recovery_queued',
      'experienceId', v_exp.id, 'queueId', v_queue_id
    );
  end if;

  v_queue_id := public.enqueue_crm_automation(
    'crm:review_invitation:experience:' || v_exp.id::text,
    'review_invitation',
    'customer_experience',
    v_exp.id::text,
    v_exp.recipient_phone,
    jsonb_build_object(
      'experience_id', v_exp.id,
      'customer_id', v_exp.customer_id,
      'first_name', v_exp.first_name,
      'service_name', v_exp.service_name,
      'satisfaction', p_satisfaction
    ),
    'google_review',
    now(),
    3
  );

  update public.crm_customer_experience
  set status = 'review_pending',
      review_queue_id = v_queue_id,
      updated_at = now()
  where id = v_exp.id;

  return jsonb_build_object(
    'matched', true, 'action', 'review_queued',
    'experienceId', v_exp.id, 'queueId', v_queue_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.register_customer_experience_request(p_source_type text, p_source_id text, p_customer_id text, p_recipient_phone text, p_first_name text, p_service_name text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_id uuid;
  v_phone text := regexp_replace(coalesce(p_recipient_phone, ''), '[^0-9]', '', 'g');
  v_existing public.crm_customer_experience%rowtype;
begin
  if coalesce(length(trim(p_source_type)), 0) = 0
     or coalesce(length(trim(p_source_id)), 0) = 0
     or length(v_phone) < 10 or length(v_phone) > 15 then
    raise exception 'Invalid customer experience source or phone' using errcode = '22023';
  end if;

  insert into public.crm_customer_experience (
    source_type, source_id, customer_id, recipient_phone,
    first_name, service_name, metadata
  ) values (
    left(trim(p_source_type), 80), left(trim(p_source_id), 160),
    nullif(left(trim(coalesce(p_customer_id, '')), 160), ''), v_phone,
    nullif(left(trim(coalesce(p_first_name, '')), 120), ''),
    nullif(left(trim(coalesce(p_service_name, '')), 200), ''),
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (source_type, source_id) do nothing
  returning id into v_id;

  if v_id is not null then
    return v_id;
  end if;

  select * into v_existing
  from public.crm_customer_experience
  where source_type = left(trim(p_source_type), 80)
    and source_id = left(trim(p_source_id), 160)
  for update;

  if not found then
    raise exception 'Customer experience row disappeared during registration';
  end if;

  if v_existing.status = 'pending_send' then
    update public.crm_customer_experience
    set customer_id = nullif(left(trim(coalesce(p_customer_id, '')), 160), ''),
        recipient_phone = v_phone,
        first_name = nullif(left(trim(coalesce(p_first_name, '')), 120), ''),
        service_name = nullif(left(trim(coalesce(p_service_name, '')), 200), ''),
        metadata = public.crm_customer_experience.metadata || coalesce(p_metadata, '{}'::jsonb),
        updated_at = now()
    where id = v_existing.id;
  end if;

  return v_existing.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_automation_queue_manual_result(p_queue_id uuid, p_outcome text, p_note text DEFAULT ''::text, p_resolved_by text DEFAULT 'crm_operator'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_job public.crm_automation_queue%rowtype;
  v_payload jsonb;
begin
  if p_outcome not in ('contacted', 'no_answer', 'rescheduled', 'not_contacted') then
    raise exception 'Unsupported manual outcome' using errcode = '22023';
  end if;
  select * into v_job from public.crm_automation_queue where id = p_queue_id for update;
  if not found or v_job.status <> 'awaiting_operator' then
    return jsonb_build_object('conflict', true);
  end if;
  v_payload := jsonb_set(
    coalesce(v_job.payload, '{}'::jsonb), '{dispatch}',
    coalesce(v_job.payload->'dispatch', '{}'::jsonb) ||
      jsonb_build_object('manual_result', p_outcome, 'manual_note', left(coalesce(p_note, ''), 500),
        'resolved_at', now(), 'resolved_by', left(coalesce(p_resolved_by, 'crm_operator'), 100)), true);
  update public.crm_automation_queue set status='completed', payload=v_payload, locked_at=null,
    completed_at=now(), last_error=null, updated_at=now() where id=p_queue_id;
  insert into public.crm_automation_attempts(queue_id, attempt_number, outcome, detail)
  values (v_job.id, coalesce(v_job.attempts,0), 'skipped',
    left('Resultado manual registrado (não é confirmação de envio): ' || p_outcome || '. ' || coalesce(p_note,''),1000));
  return jsonb_build_object('conflict',false,'item',jsonb_build_object('id',v_job.id,'status','completed'));
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_automation_queue_manual_result_v2(p_queue_id uuid, p_outcome text, p_note text DEFAULT ''::text, p_resolved_by text DEFAULT 'crm_operator'::text, p_reschedule_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_job public.crm_automation_queue%rowtype;
  v_state public.crm_app_state%rowtype;
  v_payload jsonb;
  v_tasks jsonb;
  v_task jsonb;
  v_task_id text;
  v_new_task_id text;
  v_new_task jsonb;
  v_new_queue_id uuid;
  v_revision bigint;
begin
  if p_outcome not in ('contacted', 'no_answer', 'rescheduled', 'not_contacted') then
    raise exception 'Unsupported manual outcome' using errcode = '22023';
  end if;

  if p_outcome = 'rescheduled' then
    if p_reschedule_date is null or p_reschedule_date < current_date then
      raise exception 'Reschedule date must be today or later' using errcode = '22023';
    end if;
  end if;

  select * into v_job
  from public.crm_automation_queue
  where id = p_queue_id
  for update;

  if not found or v_job.status <> 'awaiting_operator' then
    return jsonb_build_object('conflict', true, 'reason', 'queue_state');
  end if;

  if v_job.channel <> 'internal' or v_job.event_type <> 'lead_follow_up_requested' or v_job.source_type <> 'task' then
    return jsonb_build_object('conflict', true, 'reason', 'unsupported_queue_item');
  end if;

  v_task_id := coalesce(v_job.payload #>> '{dispatch,task_id}', v_job.source_id);

  select * into v_state
  from public.crm_app_state
  where id = 'main'
  for update;

  if not found then
    raise exception 'CRM state not found' using errcode = 'P0002';
  end if;

  select task into v_task
  from jsonb_array_elements(coalesce(v_state.data->'tasks', '[]'::jsonb)) as x(task)
  where task->>'id' = v_task_id
  limit 1;

  if v_task is null then
    return jsonb_build_object('conflict', true, 'reason', 'task_not_found');
  end if;

  select coalesce(jsonb_agg(
    case
      when task->>'id' = v_task_id then task || jsonb_build_object(
        'done', true,
        'completedAt', now(),
        'manualOutcome', p_outcome,
        'manualNote', left(coalesce(p_note, ''), 500)
      )
      else task
    end
    order by ord
  ), '[]'::jsonb)
  into v_tasks
  from jsonb_array_elements(coalesce(v_state.data->'tasks', '[]'::jsonb)) with ordinality as x(task, ord);

  if p_outcome = 'rescheduled' then
    v_new_task_id := gen_random_uuid()::text;
    v_new_task := jsonb_build_object(
      'id', v_new_task_id,
      'leadId', v_task->>'leadId',
      'date', p_reschedule_date::text,
      'type', coalesce(nullif(v_task->>'type', ''), 'Retorno'),
      'note', left(case when coalesce(p_note, '') = '' then 'Retorno reagendado' else p_note end, 500),
      'done', false
    );
    v_tasks := v_tasks || jsonb_build_array(v_new_task);
  end if;

  v_revision := v_state.revision + 1;
  update public.crm_app_state
  set data = jsonb_set(v_state.data, '{tasks}', v_tasks, true),
      revision = v_revision,
      updated_at = now(),
      updated_by = 'automation-manual-result'
  where id = 'main';

  v_payload := jsonb_set(
    coalesce(v_job.payload, '{}'::jsonb),
    '{dispatch}',
    coalesce(v_job.payload->'dispatch', '{}'::jsonb) || jsonb_build_object(
      'manual_result', p_outcome,
      'manual_note', left(coalesce(p_note, ''), 500),
      'resolved_at', now(),
      'resolved_by', left(coalesce(p_resolved_by, 'crm_operator'), 100)
    ),
    true
  );

  update public.crm_automation_queue
  set status = 'completed',
      payload = v_payload,
      locked_at = null,
      completed_at = now(),
      last_error = null,
      updated_at = now()
  where id = p_queue_id;

  insert into public.crm_automation_attempts(queue_id, attempt_number, outcome, detail)
  values (
    v_job.id,
    coalesce(v_job.attempts, 0),
    'skipped',
    left('Resultado manual registrado (não é confirmação de envio): ' || p_outcome || '. ' || coalesce(p_note, ''), 1000)
  );

  if p_outcome = 'rescheduled' then
    v_new_queue_id := public.enqueue_crm_automation(
      'crm:lead_follow_up_requested:task:' || v_new_task_id,
      'lead_follow_up_requested',
      'task',
      v_new_task_id,
      null,
      jsonb_build_object(
        'source_type', 'task',
        'source_id', v_new_task_id,
        'occurred_at', now(),
        'task', 'follow_up_lead',
        'rescheduled_from', v_task_id
      ),
      'internal',
      now(),
      3
    );
  end if;

  return jsonb_build_object(
    'conflict', false,
    'item', jsonb_build_object('id', v_job.id, 'status', 'completed'),
    'appRevision', v_revision,
    'rescheduledTaskId', v_new_task_id,
    'rescheduledQueueId', v_new_queue_id,
    'rescheduleDate', case when p_reschedule_date is null then null else p_reschedule_date::text end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_automation_queue_manual_result_v3(p_queue_id uuid, p_outcome text, p_note text DEFAULT ''::text, p_resolved_by text DEFAULT 'crm_operator'::text, p_reschedule_date date DEFAULT NULL::date, p_reschedule_time text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_job public.crm_automation_queue%rowtype;
  v_state public.crm_app_state%rowtype;
  v_payload jsonb;
  v_tasks jsonb;
  v_task jsonb;
  v_task_id text;
  v_new_task_id text;
  v_new_task jsonb;
  v_new_queue_id uuid;
  v_revision bigint;
  v_time text;
begin
  if p_outcome not in ('contacted', 'no_answer', 'rescheduled', 'not_contacted') then
    raise exception 'Unsupported manual outcome' using errcode = '22023';
  end if;

  v_time := nullif(btrim(coalesce(p_reschedule_time, '')), '');
  if p_outcome = 'rescheduled' then
    if p_reschedule_date is null or p_reschedule_date < current_date then
      raise exception 'Reschedule date must be today or later' using errcode = '22023';
    end if;
    if v_time is not null and v_time !~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9]$' then
      raise exception 'Reschedule time must be HH:MM' using errcode = '22023';
    end if;
  else
    v_time := null;
  end if;

  select * into v_job from public.crm_automation_queue where id = p_queue_id for update;
  if not found or v_job.status <> 'awaiting_operator' then
    return jsonb_build_object('conflict', true, 'reason', 'queue_state');
  end if;
  if v_job.channel <> 'internal' or v_job.event_type <> 'lead_follow_up_requested' or v_job.source_type <> 'task' then
    return jsonb_build_object('conflict', true, 'reason', 'unsupported_queue_item');
  end if;

  v_task_id := coalesce(v_job.payload #>> '{dispatch,task_id}', v_job.source_id);
  select * into v_state from public.crm_app_state where id = 'main' for update;
  if not found then raise exception 'CRM state not found' using errcode = 'P0002'; end if;

  select task into v_task
  from jsonb_array_elements(coalesce(v_state.data->'tasks', '[]'::jsonb)) as x(task)
  where task->>'id' = v_task_id limit 1;
  if v_task is null then return jsonb_build_object('conflict', true, 'reason', 'task_not_found'); end if;

  select coalesce(jsonb_agg(
    case when task->>'id' = v_task_id then task || jsonb_build_object(
      'done', true, 'completedAt', now(), 'manualOutcome', p_outcome,
      'manualNote', left(coalesce(p_note, ''), 500)
    ) else task end order by ord
  ), '[]'::jsonb)
  into v_tasks
  from jsonb_array_elements(coalesce(v_state.data->'tasks', '[]'::jsonb)) with ordinality as x(task, ord);

  if p_outcome = 'rescheduled' then
    v_new_task_id := gen_random_uuid()::text;
    v_new_task := jsonb_build_object(
      'id', v_new_task_id, 'leadId', v_task->>'leadId', 'date', p_reschedule_date::text,
      'type', coalesce(nullif(v_task->>'type', ''), 'Retorno'),
      'note', left(case when coalesce(p_note, '') = '' then 'Retorno reagendado' else p_note end, 500),
      'done', false
    );
    if v_time is not null then v_new_task := v_new_task || jsonb_build_object('time', v_time); end if;
    v_tasks := v_tasks || jsonb_build_array(v_new_task);
  end if;

  v_revision := v_state.revision + 1;
  update public.crm_app_state
  set data = jsonb_set(v_state.data, '{tasks}', v_tasks, true),
      revision = v_revision, updated_at = now(), updated_by = 'automation-manual-result-v3'
  where id = 'main';

  v_payload := jsonb_set(
    coalesce(v_job.payload, '{}'::jsonb), '{dispatch}',
    coalesce(v_job.payload->'dispatch', '{}'::jsonb) || jsonb_build_object(
      'manual_result', p_outcome, 'manual_note', left(coalesce(p_note, ''), 500),
      'resolved_at', now(), 'resolved_by', left(coalesce(p_resolved_by, 'crm_operator'), 100)
    ), true
  );

  update public.crm_automation_queue
  set status = 'completed', payload = v_payload, locked_at = null, completed_at = now(),
      last_error = null, updated_at = now()
  where id = p_queue_id;

  insert into public.crm_automation_attempts(queue_id, attempt_number, outcome, detail)
  values (v_job.id, coalesce(v_job.attempts, 0), 'skipped',
    left('Resultado manual registrado (não é confirmação de envio): ' || p_outcome || '. ' || coalesce(p_note, ''), 1000));

  if p_outcome = 'rescheduled' then
    v_new_queue_id := public.enqueue_crm_automation(
      'crm:lead_follow_up_requested:task:' || v_new_task_id,
      'lead_follow_up_requested', 'task', v_new_task_id, null,
      jsonb_build_object('source_type','task','source_id',v_new_task_id,'occurred_at',now(),'task','follow_up_lead','rescheduled_from',v_task_id),
      'internal', now(), 3
    );
  end if;

  return jsonb_build_object(
    'conflict', false,
    'item', jsonb_build_object('id', v_job.id, 'status', 'completed'),
    'appRevision', v_revision,
    'rescheduledTaskId', v_new_task_id,
    'rescheduledQueueId', v_new_queue_id,
    'rescheduleDate', case when p_reschedule_date is null then null else p_reschedule_date::text end,
    'rescheduleTime', v_time
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_customer_experience_recovery(p_queue_id uuid, p_outcome text, p_note text DEFAULT ''::text, p_resolved_by text DEFAULT 'crm_operator'::text, p_reschedule_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_job public.crm_automation_queue%rowtype;
  v_exp public.crm_customer_experience%rowtype;
  v_review_queue_id uuid;
  v_scheduled_at timestamptz;
begin
  if p_outcome not in ('resolved','unresolved','rescheduled') then
    raise exception 'Unsupported recovery outcome' using errcode = '22023';
  end if;

  if p_outcome = 'rescheduled' and (p_reschedule_date is null or p_reschedule_date < current_date) then
    raise exception 'Reschedule date must be today or later' using errcode = '22023';
  end if;

  select * into v_job
  from public.crm_automation_queue
  where id = p_queue_id
  for update;

  if not found or v_job.status <> 'awaiting_operator'
     or v_job.channel <> 'internal'
     or v_job.event_type <> 'service_recovery_required'
     or v_job.source_type <> 'customer_experience' then
    return jsonb_build_object('conflict', true, 'reason', 'queue_state');
  end if;

  select * into v_exp
  from public.crm_customer_experience
  where id::text = v_job.source_id
  for update;

  if not found or v_exp.status <> 'recovery_in_progress' then
    return jsonb_build_object('conflict', true, 'reason', 'experience_state');
  end if;

  if p_outcome = 'rescheduled' then
    v_scheduled_at := p_reschedule_date::timestamp + time '12:00';
    update public.crm_automation_queue
    set status = 'pending',
        scheduled_at = v_scheduled_at,
        locked_at = null,
        last_error = null,
        payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
          'last_manual_note', left(coalesce(p_note, ''), 500),
          'rescheduled_by', left(coalesce(p_resolved_by, 'crm_operator'), 100),
          'rescheduled_at', now()
        ),
        updated_at = now()
    where id = v_job.id;

    update public.crm_customer_experience
    set recovery_note = left(coalesce(p_note, ''), 1000),
        updated_at = now()
    where id = v_exp.id;

    return jsonb_build_object(
      'conflict', false, 'rescheduled', true,
      'experienceId', v_exp.id, 'rescheduleDate', p_reschedule_date::text
    );
  end if;

  update public.crm_automation_queue
  set status = 'completed',
      locked_at = null,
      completed_at = now(),
      last_error = null,
      payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
        'recovery_outcome', p_outcome,
        'recovery_note', left(coalesce(p_note, ''), 500),
        'resolved_by', left(coalesce(p_resolved_by, 'crm_operator'), 100),
        'resolved_at', now()
      ),
      updated_at = now()
  where id = v_job.id;

  v_review_queue_id := public.enqueue_crm_automation(
    'crm:review_invitation:experience:' || v_exp.id::text,
    'review_invitation',
    'customer_experience',
    v_exp.id::text,
    v_exp.recipient_phone,
    jsonb_build_object(
      'experience_id', v_exp.id,
      'customer_id', v_exp.customer_id,
      'first_name', v_exp.first_name,
      'service_name', v_exp.service_name,
      'recovery_outcome', p_outcome
    ),
    'google_review',
    now() + interval '1 hour',
    3
  );

  update public.crm_customer_experience
  set status = 'review_pending',
      recovery_outcome = p_outcome,
      recovery_note = left(coalesce(p_note, ''), 1000),
      recovery_resolved_at = now(),
      review_queue_id = v_review_queue_id,
      updated_at = now()
  where id = v_exp.id;

  insert into public.crm_automation_attempts(queue_id, attempt_number, outcome, detail)
  values (
    v_job.id,
    coalesce(v_job.attempts, 0),
    'skipped',
    left('Recuperação registrada manualmente: ' || p_outcome || '. ' || coalesce(p_note, ''), 1000)
  )
  on conflict do nothing;

  return jsonb_build_object(
    'conflict', false,
    'experienceId', v_exp.id,
    'reviewQueueId', v_review_queue_id,
    'reviewScheduled', true
  );
end;
$function$
